/**
 * @method
 * @name input_55_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input_55_onclick = async function(e){
    try {
