/**
 * @method
 * @name grd_docPageList_oncellclick
 * @description grd_docPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_docPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.shareFileUpload(r["applNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.oncellclick' });
    }
};

/**
 * @method
 * @name input_105_onclick
 * @description 「공유 정보 등록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_105_onclick = async function(e){
    try {
        await scwin.shareFileUpload('')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70401.input_105_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_delete_do
 * @description delete do 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delete_do = async function () {
    const sbmOptions = {
        id: "tx_fn_delete_do",
        method: "post",
        action: "/discls/searchDisclosureDocument.do?method=removeCompltDocument",
        ref: "dma_deleteDoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn__doc_delete_do
 * @description doc delete do 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn__doc_delete_do = async function () {
    const sbmOptions = {
        id: "tx_fn__doc_delete_do",
        method: "post",
        action: "/discls/searchDisclosureDocument.do?method=removeWritingDocument",
        ref: "dma_DocDeleteDoReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_preview
 * @description preview 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_preview = async function () {
    try { return await $c.data.downFile("/discls/disclosure.do?method=searchDocumentPrint", "", ($c.util.getComponent("dma_previewReq") ? $c.util.getComponent("dma_previewReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
