    try { return await $c.data.downFile("/discls/fssFile.do", "", ($c.util.getComponent("dma_fssFileUploadReq") ? $c.util.getComponent("dma_fssFileUploadReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
