/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/discls/disclosure.do",
        ref: "dma_loadListReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldods70401.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] !== null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot !== null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_102").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_docPageList_fmt_corpUsrNm
 * @description grd doc Page List fmt corp Usr Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_corpUsrNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "kclicUsrTpId") ?? '') : '');
        if (v === 'LIST_CORP_DISCLS') { return "공시담당자"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.corpUsrNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name enterSearchForm
 * @description enter Search Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.enterSearchForm = async function () {
    if (event.keyCode === 13) {
        await scwin.searchList();
    }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('ipt_fromDate').getValue()> $c.util.getComponent('ipt_toDate').getValue()) {
        await alertE('시작일자는 종료일자 이전 이어야 합니다.');
        return;
    }
    blockLoading();
    /* 수동 전환 필요: searchForm.submit() — as-is 자기제출(action 없음), 대체 tx 미정 */ await $c.win.alert("이 동작은 아직 전환되지 않았습니다(as-is 폼 «searchForm» 자기제출 — 대체 서버 호출 미정).");
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {*} applNo applNo
 * @returns {void}
 * @hidden N
 */
scwin.delete = function (applNo) {
    confirmF("삭제하시겠습니까?", async function() {
            await scwin.deleteDo(applNo);
    });
};

/**
 * @method
 * @name deleteDo
 * @description delete Do 처리
 * @param {*} applNo applNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteDo = async function (applNo) {
    (document.searchForm || { elements: [] }).action = "/discls/searchDisclosureDocument.do?method=removeCompltDocument";
    $c.util.getComponent('dma_deleteDoReq').set('applNo', applNo);
    await scwin.tx_fn_delete_do();
};

/**
 * @method
 * @name docDelete
 * @description doc Delete 처리
 * @param {*} applNo applNo
 * @returns {void}
 * @hidden N
 */
scwin.docDelete = function (applNo) {
    confirmF("삭제하시겠습니까?", async function() {
            await scwin.docDeleteDo(applNo);
    });
};

/**
 * @method
 * @name docDeleteDo
 * @description doc Delete Do 처리
 * @param {*} applNo applNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.docDeleteDo = async function (applNo) {
    (document.searchForm || { elements: [] }).action = "/discls/searchDisclosureDocument.do?method=removeWritingDocument";
    $c.util.getComponent('dma_deleteDoReq').set('applNo', applNo);
    await scwin.tx_fn__doc_delete_do();
};

/**
 * @method
 * @name preview
 * @description preview 처리
 * @param {*} applNo applNo
 * @param {String} formNm formNm
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} tgtIsurCd tgtIsurCd
 * @param {*} tgtFssUnqNo tgtFssUnqNo
 * @param {String} odsDisclsProcsStatCd odsDisclsProcsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.preview = async function (applNo, formNm, formCd, formVer, tgtIsurCd, tgtFssUnqNo, odsDisclsProcsStatCd) {
    $c.util.getComponent('dma_deleteDoReq').set('applNo', applNo);
    $c.util.getComponent('dma_deleteDoReq').set('formCd', formCd);
    $c.util.getComponent('dma_deleteDoReq').set('formVer', formVer);
    $c.util.getComponent('dma_deleteDoReq').set('disclsMaindocFormCd', formCd);
    $c.util.getComponent('dma_deleteDoReq').set('disclsMaindocFormVer', formVer);
    $c.util.getComponent('dma_deleteDoReq').set('tgtIsurCd', tgtIsurCd);
    $c.util.getComponent('dma_deleteDoReq').set('tgtFssUnqNo', tgtFssUnqNo);
    $c.util.getComponent('dma_deleteDoReq').set('disclsDocTxtfile', formNm);
    $c.util.getComponent('dma_deleteDoReq').set('odsDisclsProcsStatCd', odsDisclsProcsStatCd);
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    scwin.printWin = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "about:Blank", unresolved: "nav:" + "about:Blank" }; })();
    (document.printFrm || { elements: [] }).target = 'printWin';
    (document.printFrm || { elements: [] }).action = 'disclosure.do?method=searchDocumentPrint';
    await scwin.tx_fn_preview();
};

/**
 * @method
 * @name previewPop
 * @description preview Pop 처리
 * @param {*} applNo applNo
 * @param {String} formNm formNm
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} tgtIsurCd tgtIsurCd
 * @param {*} tgtFssUnqNo tgtFssUnqNo
 * @param {String} odsDisclsProcsStatCd odsDisclsProcsStatCd
 * @param {String} integUsrId integUsrId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.previewPop = async function (applNo, formNm, formCd, formVer, tgtIsurCd, tgtFssUnqNo, odsDisclsProcsStatCd, integUsrId) {
    $c.util.getComponent('dma_deleteDoReq').set('applNo', applNo);
    $c.util.getComponent('dma_deleteDoReq').set('formCd', formCd);
    $c.util.getComponent('dma_deleteDoReq').set('formVer', formVer);
    $c.util.getComponent('dma_deleteDoReq').set('tgtIsurCd', tgtIsurCd);
    $c.util.getComponent('dma_deleteDoReq').set('tgtFssUnqNo', tgtFssUnqNo);
    $c.util.getComponent('dma_deleteDoReq').set('disclsDocTxtfile', formNm);
    $c.util.getComponent('dma_deleteDoReq').set('odsDisclsProcsStatCd', odsDisclsProcsStatCd);
    $c.util.getComponent('dma_deleteDoReq').set('integUsrId', integUsrId);
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    scwin.printWin = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "about:Blank", unresolved: "nav:" + "about:Blank" }; })();
    (document.printFrm || { elements: [] }).target = 'printWin';
